let PREFS = { remindMins: 15, sessionGoal: 0, typewriter: true, dimOthers: true, uncitedMin: 40, spellcheck: true };
try { Object.assign(PREFS, JSON.parse(lsGet(PREFS_KEY) || '{}')); } catch (e) {}
