/* ---------------- dialogs, toast, misc ---------------- */
function ask(title, msg, okLabel = 'OK', inputValue = null) {
  return new Promise(res => {
    const d = $('#askDlg'), inp = $('#askInput');
    $('#askTitle').textContent = title; $('#askMsg').textContent = msg; $('#askOk').textContent = okLabel;
    $('#askOk').classList.toggle('danger', /delete|discard/i.test(okLabel));
    inp.classList.toggle('hidden', inputValue === null); if (inputValue !== null) inp.value = inputValue;
    const fin = v => { d.close(); $('#askOk').onclick = $('#askCancel').onclick = inp.onkeydown = d.oncancel = null; res(v); };
    $('#askOk').onclick = () => fin(inputValue !== null ? inp.value.trim() : true);
    $('#askCancel').onclick = () => fin(inputValue !== null ? null : false);
    d.oncancel = () => fin(inputValue !== null ? null : false);
    inp.onkeydown = e => { if (e.key === 'Enter') $('#askOk').click(); };
    d.showModal(); setTimeout(() => (inputValue !== null ? inp : $('#askOk')).focus(), 30);
  });
}
function infoDialog(title, html) { $('#infoTitle').textContent = title; $('#infoBody').innerHTML = html; $('#infoDlg').showModal(); $('#infoOk').focus(); }
$('#infoOk').addEventListener('click', () => $('#infoDlg').close());
let toastT;
function toast(msg, action) {
  const t = $('#toast'); t.textContent = msg; t.classList.toggle('has-act', !!action);
  // over an open dialog, the toast goes inside it so it shows above the backdrop and its button can be clicked
  let host = document.body; try { host = [...document.querySelectorAll('dialog[open]')].filter(d => d.matches(':modal')).pop() || document.body; } catch (e) { /* :modal unsupported */ }
  if (t.parentElement !== host) { host.append(t); if (host !== document.body) host.addEventListener('close', () => { const up = [...document.querySelectorAll('dialog[open]')].filter(d => d.matches(':modal')).pop() || document.body; up.append(t); }, { once: true }); }
  if (action) { const b = document.createElement('button'); b.className = 'toast-act'; b.textContent = action.label; b.addEventListener('click', () => { t.classList.remove('show'); action.fn(); }); t.append(b); }
  t.classList.add('show'); clearTimeout(toastT); toastT = setTimeout(() => t.classList.remove('show'), action ? 6000 : 2800);
}
function switchTab(name) {
  $$('.tabs button').forEach(b => b.classList.toggle('on', b.dataset.tab === name));
  $$('.pane').forEach(p => p.classList.toggle('on', p.dataset.pane === name));
}
$$('.tabs button').forEach(b => b.addEventListener('click', () => switchTab(b.dataset.tab)));
$('#btnSide').addEventListener('click', () => {
  const b = document.body;
  if (innerWidth > 860) { const hide = !b.classList.contains('side-hidden') || b.classList.contains('side-open'); b.classList.remove('side-open'); b.classList.toggle('side-hidden', hide); PREFS.sideHidden = hide; savePrefs(); pbSoon(); }
  else b.classList.toggle('side-open');
});
$('#scrim').addEventListener('click', () => document.body.classList.remove('side-open'));
if (PREFS.sideHidden) document.body.classList.add('side-hidden');
$('#btnSave').addEventListener('click', () => saveProject(false));
$('#btnOpen').addEventListener('click', openProject);
$('#btnNewProj').addEventListener('click', () => openNewProject());
$('#fileOpen').addEventListener('change', async e => { const f = e.target.files[0]; e.target.value = ''; if (f) loadProjectText(await f.text(), null, f.name); });
function fillHelpTips() { const h = $('#helpTips'); if (h && !h.childElementCount) h.innerHTML = Object.values(TIPS).map(t => `<details><summary>${esc(t.label)}</summary><ul>${t.tips.map(x => `<li>${esc(x)}</li>`).join('')}</ul></details>`).join(''); }
$('#btnHelp').addEventListener('click', () => { fillHelpTips(); $('#helpDlg').showModal(); });
