$('#replQ').addEventListener('keydown', e => { if (e.key === 'Enter') { e.preventDefault(); $('#replOne').click(); } if (e.key === 'Escape') closeFind(); });
$('#findNext').addEventListener('click', () => stepFind(1));
$('#findPrev').addEventListener('click', () => stepFind(-1));
