  [['data-credit', '#crCredit'], ['data-rights', '#crRights'], ['data-holder', '#crHolder'], ['data-rnote', '#crNote']].forEach(([a, sel]) => { const v = $(sel).value.trim(); if (v) f.setAttribute(a, v); else f.removeAttribute(a); });
