function eqRemove() { const t = eqTarget; eqTarget = null; $('#eqDlg').close(); if (t && t.isConnected) { if (t.nodeName === 'SPAN') eqUnplace(t); else t.remove(); renumberFigures(); onEdit(); markDirty(); toast('Equation removed.'); } }
