    const tpl = document.createElement('template'); let last = 0, h = '', m;
    while ((m = re.exec(tn.data))) { h += esc(tn.data.slice(last, m.index)) + eqHTML((m[1] || m[2] || m[3]).trim(), false); last = re.lastIndex; n++; }
