  let lo = Math.min(...ev.map(e => e.a)), hi = Math.max(...ev.map(e => e.b ?? e.a)); if (hi - lo < 0.08) { lo -= .05; hi += .05; }
  const span = hi - lo; lo -= span * .03; hi += span * .03;
