function ghPath() { const c = ghCfg(); return c.paths[P.id] || `${(c.folder || 'anabasis').replace(/^\/+|\/+$/g, '')}/${fileSafe(P.title || 'project').replace(/\s+/g, '-')}-${P.id.slice(-6)}.json`; }
