  if (c.percent === 'symbol') add('percent', '“percent” → “%”', /(\d)\s(?:percent|per cent)\b/g, mt => mt[1] + '%');
  if (c.us === 'US') add('us', '“U.S.” → “US”', /\bU\.S\.(?![\w])/g, () => 'US');
