  const a = e.target.closest('[data-oa]'); if (a) { const fn = ORC.acts[+a.dataset.oa]; if (fn) fn(); return; }
  const q = e.target.closest('[data-oq]'); if (q) { orcTurn(q.dataset.oq); $('#orcIn')?.focus(); return; }
