  if (thLi && a) { const t = thById(thLi.dataset.thid); if (!t) return; if (a === 'eye') { t.hidden = !t.hidden; markDirty(); renderResearch(); } else rmStep('th', t.id, a === 'next' ? 1 : -1); return; }
  if (j) { const fn = rsEls[+j.dataset.j]; if (fn) fn(); }
