  if (top && top.sg === label && now - sgLast < 1500 && rmMatches(top.after)) { fn(); top.after = rmSnap(); }
  else { rmOp(label, fn); const t = RM_UNDO[RM_UNDO.length - 1]; if (t) t.sg = label; }
