/* ---------- reviewing ---------- */
const sgAll = (root = editor) => { const by = new Map(); $$('ins.sg,del.sg', root).forEach(el => { const k = el.dataset.sg; if (!by.has(k)) by.set(k, []); by.get(k).push(el); }); return [...by.values()]; };
