const LOC_PANDOC = { page: 'p.', chapter: 'chap.', section: 'sec.', paragraph: 'para.', line: 'l.', figure: 'fig.', table: 'tbl.', volume: 'vol.', part: 'pt.', note: 'n.', column: 'col.', folio: 'fol.', verse: 'v.', book: 'bk.' };
