    let md = td().turndown(tmp.innerHTML);
    md = md.replace(/ZZC(\d+)ZZ/g, (m, j) => pandocCite(x.cites[+j], keys)).replace(/ZZF(\d+)ZZ/g, (m, j) => `^[${x.fns[+j].replace(/[\[\]]/g, '\\$&')}]`);
