  renderNoteList(); renderHomeSoon();
  toast(`${made.length} ${made.length === 1 ? 'note' : 'notes'} made from ${whole ? 'the pad' : 'the selection'}. Find ${made.length === 1 ? 'it' : 'them'} in Notes and the board inbox.`, { label: 'Undo', fn: undo });
