  if (!slushText(html) && !/<(img|figure|table)\b/i.test(html)) return null;
  const it = { id: uid('sl'), html, title: x.title || '', from: x.from || '', fromTitle: x.fromTitle || '', kind: x.kind || 'cut', at: nowISO(), note: '' };
  if (x.doc) it.doc = x.doc;
