    const only = t.children.length === 1 && t.firstElementChild.tagName === 'P' ? t.firstElementChild.innerHTML : t.innerHTML;
    editor.focus(); insertHTMLAtCursor(only); syncEditor(); markDirty();
    const undo = slushTake(x, keep);
