  lnApply(); markDirty();
  toast(kind === 'para' ? (d.layout.paraNums ? 'Paragraphs numbered, here and in every export.' : 'Paragraph numbers off.') : (d.layout.lineNums ? 'Lines numbered, here and in PDF and Word.' : 'Line numbers off.'));
