COMMANDS.push(['The Oracle: what should I work on next?', () => { openOracle(); setTimeout(() => orcTurn('what should I work on next?'), 120); }], ['The Oracle: wrap up the day', () => { openOracle(); setTimeout(() => orcTurn('wrap up'), 120); }]);

/* ================================================================
   Installable app. On the hosted copy (GitHub Pages), Anabasis registers a
   service worker so it can be added to the Home Screen and opened offline.
   Opened as a file, none of this runs.
   ================================================================ */
function setupInstall() {
  // only the hosted copy built by tools/site/build_site.py carries this marker (and ships sw.js beside it)
  if (!document.querySelector('meta[name=anabasis-installable]') || !('serviceWorker' in navigator) || !window.isSecureContext || location.protocol === 'file:') return;
  navigator.serviceWorker.register('sw.js').then(() => {
    if (!$('link[rel=manifest]')) { const l = document.createElement('link'); l.rel = 'manifest'; l.href = 'manifest.webmanifest'; document.head.append(l); }
    document.documentElement.classList.add('installable');
  }).catch(() => {});
}
const isStandalone = () => matchMedia('(display-mode: standalone)').matches || navigator.standalone === true;
/* 2.9: install from inside the app, the way Chrome and Edge offer it in the address bar. Only the hosted copy can be
   installed: browsers install apps from a website, never from a file on your computer. */
var installEvt = null;
addEventListener('beforeinstallprompt', e => { e.preventDefault(); installEvt = e; installRender(); });
addEventListener('appinstalled', () => { installEvt = null; installRender(); toast('Anabasis is installed. Open it from your Dock, Start menu or home screen, even offline.'); });
const HOSTED_URL = 'https://zerohistory.net/anabasis/app/';
function installRender() {
  const el = $('#stInstall'); if (!el) return;
  const ios = /iPad|iPhone|iPod/.test(navigator.userAgent) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1), safari = /^((?!chrome|android|crios|fxios|edg).)*safari/i.test(navigator.userAgent);
  if (isStandalone()) el.textContent = 'Installed. Anabasis opens in its own window and works offline.';
  else if (installEvt) el.innerHTML = `<button class="small primary-soft" id="stInstallGo">Install Anabasis</button> <span class="muted">Its own window, a Dock or Start menu icon, and it works offline.</span>`;
  else if (location.protocol === 'file:' || !IS_HOSTED) el.innerHTML = `This copy is a file, and browsers install apps only from a website. Open the hosted copy, <a href="${HOSTED_URL}" target="_blank" rel="noopener">zerohistory.net/anabasis/app</a>, and install it from there. Your work moves across with <b>Save</b> and <b>Open</b>.`;
  else if (ios) el.innerHTML = 'On an iPhone or iPad: tap <b>Share</b>, then <b>Add to Home Screen</b>.';
  else if (safari) el.innerHTML = 'In Safari: <b>File → Add to Dock</b> (or Share → Add to Dock).';
  else el.innerHTML = 'In Chrome or Edge, choose the install icon at the right of the address bar, or ⋮ → <b>Cast, save and share → Install page as app</b>. Firefox doesn’t install web apps.';
}
document.addEventListener('click', async e => {
  if (e.target.id !== 'stInstallGo' || !installEvt) return;
  const ev = installEvt; installEvt = null; ev.prompt();
  try { const r = await ev.userChoice; if (r && r.outcome !== 'accepted') installEvt = null; } catch (err) {}
  installRender();
});
COMMANDS.push(['Install Anabasis as an app', () => { if (installEvt) { $('#stInstallGo') ? $('#stInstallGo').click() : (openSettings(), setTimeout(() => $('#stInstallGo')?.click(), 50)); } else { openSettings(); setTimeout(() => $('#stInstall').scrollIntoView({ block: 'center' }), 60); } }]);
if (isStandalone()) document.documentElement.classList.add('standalone');
{ const k = $('#btnSearch kbd'); if (k) k.textContent = IS_MAC ? '⌘K' : 'Ctrl K'; }

/* ---------------- boot ---------------- */
function sendClip(to, clip) {
  return new Promise(res => {
    const t = setTimeout(() => { bc.removeEventListener('message', on); res(false); }, 1500);
    const on = e => { const m = e.data || {}; if (m.type === 'clip-ok' && m.to === TAB_ID) { clearTimeout(t); bc.removeEventListener('message', on); res(true); } };
    bc.addEventListener('message', on);
    bc.postMessage({ type: 'clip', to, from: TAB_ID, clip });
  });
}
(async function boot() {
  if (POPOUT) { popoutBoot(); return; }
  const clip = readClipFromHash();
  if (clip) {
    const other = await findOtherTab(true);
    if (other && await sendClip(other, clip)) {
      document.body.innerHTML = '<div class="handoff"><div><b>Clipped to Anabasis ✓</b><p>It’s in your open Anabasis tab. You can close this one.</p></div></div>';
      try { window.close(); } catch (e) {}
      return;
    }
  }
  window.name = 'commonplace';
  const th = lsGet(THEME_KEY) || (matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');
  document.documentElement.dataset.theme = th;
  let rec = await loadLocal();
  if (isLocked(rec)) {
    const r = await unlockLoop(rec, 'Unlock Anabasis', 'Your project in this browser is locked with a password.', true);
    if (r === '__fresh') {
      if (await ask('Start without it?', 'This erases the locked copy kept in this browser. Locked project files you saved are not touched, and you can open them with the password later.', 'Erase browser copy')) { try { await idb.set(STORE_KEY, ''); } catch (e) {} lsSet(STORE_KEY, ''); rec = null; lsSet('commonplace.fresh', '1'); }
      else { location.reload(); return; }
    } else if (r && r.text) { try { rec = JSON.parse(r.text); LOCK = r.lock; document.body.classList.add('locked'); } catch (e) { rec = null; } }
    else rec = null;
  }
  if (rec && rec.project) {
    P = normalize(rec.project); curDocId = rec.curDocId;
    dirtyFile = rec.dirtyFile !== undefined ? !!rec.dirtyFile : true;
    dirtySince = dirtyFile ? (rec.dirtySince || Date.now()) : null;
    lastFileSave = rec.lastFileSave ? new Date(rec.lastFileSave) : null; lastFileName = rec.lastFileName || '';
  } else if (lsGet('commonplace.fresh')) { P = blankProject(); P.docs.push(newDoc()); try { localStorage.removeItem('commonplace.fresh'); } catch (e) {} }
  else P = sampleProject();
  if (!P.docs.length) P.docs.push(newDoc());
  openDoc(P.docs.find(d => d.id === curDocId) ? curDocId : binderOrder()[0].id, true);
  renderAll(); updateSaveState();
  appReady = true; applyWritingView(); pbLayoutAll(); setupInstall();
  restoreAutosaveHandle();
  if (!clip) findOtherTab(false).then(o => { if (o) showTabWarning(); });
  if (!clip && FIRST_VISIT && !PREFS.toured) setTimeout(() => startTour(), 350);
  else if (!clip && PREFS.startHome !== false) openHome();
  if (rec && rec.project && dirtyFile && !clip) toast('Restored your unsaved work from this browser.');
  if (clip) handleClip(clip);
  else { setTimeout(() => ghCheckNewer(true), 1500); wnCheck(); setTimeout(updMaybe, 4000); }
})();
